#ifdef GL_ES
  precision highp float;
  precision highp sampler2D;
#endif

#define PI 3.14159265359

vec3 hash33(vec3 p3)
{
    p3 = fract(p3 * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yxz + 33.33);
    vec3 res = fract(p3);
    return (res - 0.5) * 0.5 + 0.5;
}

float minkowski_dist(vec3 a, vec3 b, float p)
{
    vec3 diff = abs(a - b);
    vec3 powDiff = pow(diff, vec3(p));
    float sum = powDiff.x + powDiff.y + powDiff.z;
    return pow(sum, 1.0 / p);
}

vec4 voronoi3D(vec3 p)
{
    vec3 pg = floor(p);
    vec3 pc = fract(p);

    float d = 1.0;
    vec3 c = vec3(100.0);
    vec3 pv = vec3(0.0);

    // 预计算偏移量数组
    vec3 offsets[8];
    offsets[0] = vec3(-1.0, -1.0, -1.0);
    offsets[1] = vec3(0.0, -1.0, -1.0);
    offsets[2] = vec3(-1.0, 0.0, -1.0);
    offsets[3] = vec3(0.0, 0.0, -1.0);
    offsets[4] = vec3(-1.0, -1.0, 0.0);
    offsets[5] = vec3(0.0, -1.0, 0.0);
    offsets[6] = vec3(-1.0, 0.0, 0.0);
    offsets[7] = vec3(0.0, 0.0, 0.0);

    for (int i = 0; i < 8; i++)
    {
        vec3 n = offsets[i];
        vec3 pn = hash33(pg + n);
        float dn = minkowski_dist(n + pn, pc, 0.65);

        if (d > dn)
        {
            d = dn;
            c = n;
            pv = pn + n - pc;
        }
    }

    pg += c;
    return vec4(pv.x, d, pg.x, pg.y);
}

vec4 getColor(vec2 uv, float timeOffset)
{
    float c = 9.0;
    float t = mod(timeOffset, 100.0);
    t = floor(t * c) / c; // 保持原来的计算
    float size = 6.0;

    // 计算 Voronoi 结果
    vec4 vt = voronoi3D(vec3(uv * size, t));
    float s = 1.0 - vt.y;

    // 使用 vec4 处理颜色
    vec4 vseg = vec4(hash33(vec3(vt.z, vt.w, 1.0)), 1.0); // 直接使用 vec4
    float seg = 12.0 + 8.0 * (vseg.r * 3.0 + vseg.g * 2.0 + vseg.b * 5.0); // 使用 vseg 的 r, g, b 分量

    // 返回最终颜色
    return vec4(vseg.rgb, s * sin(mod(seg * (iTime + 5.0) * 0.008, 2.0) * PI));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    float cEffectSeed = 0.0;
    uv.x += 0.015 * iTime;
    uv.y *= 1.1;
    vec4 seg = getColor(uv, cEffectSeed);
    float m = seg.a;
    m = max(m, getColor(uv + vec2(119.3, 4.5), cEffectSeed + 30.0).a);
    m = smoothstep(0.3, 0.8, m);
    vec3 color = seg.rgb * 1.4;
    if(color.r + color.g + color.b > 2.3)
    {
        color = vec3(1.0);
    }
    else
    {
        color = vec3(1.0, 0.725, 0.173);
    }

    // fragColor = vec4(mix(color, vec3(0.0), m), 1.0);
    fragColor = vec4(vec3(m) * color, 1.0);
}
